 function resize(){const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.position.z=w<500?8.2:w/h<1.15?7.8:7.1;camera.position.y=w<500?-.18:0;camera.updateProjectionMatrix();render()}
 function animate(t){if(disposed)return;const dt=last?Math.min((t-last)/1000,.05):0;last=t;phase+=dt;const blend=1-Math.exp(-dt*7);mx+=(targetX-mx)*blend;my+=(targetY-my)*blend;amount+=(amountTarget-amount)*blend;positionParts();key.position.x=-3+Math.sin(phase*.45)*.65+mx;group.rotation.set(-.07+Math.sin(phase*.4)*.055+my*.1,.12+Math.sin(phase*.3)*.13+mx*.22,-.035+Math.sin(phase*.27)*.035);group.position.y=Math.sin(phase*.6)*.045;render();if(visible&&!paused&&!document.hidden)raf=requestAnimationFrame(animate)}
