 motion.addEventListener('click',()=>{paused=!paused;update();schedule()});media.addEventListener('change',e=>{paused=e.matches;update();schedule()});document.addEventListener('visibilitychange',schedule);const ro=new ResizeObserver(resize);ro.observe(host);const io=new IntersectionObserver(es=>{visible=es[0].isIntersecting;schedule()});io.observe(host);
